import csv, numpy as np
from collections import defaultdict
def run(src,h):
    R=list(csv.DictReader(open(src,encoding="utf-8")))
    def acc(r):
        try: return float(r["surgeB"])>=3 and float(r["imbB"])>=0.1
        except: return False
    m={}
    for sel in (True,False):
        d=defaultdict(list)
        for r in R:
            if acc(r)==sel and r["M%d"%h]!="": d[r["инструмент"]].append(float(r["M%d"%h]))
        m[sel]={k:np.median(v) for k,v in d.items() if len(v)>=5}
    both=[k for k in m[True] if k in m[False]]
    print(src,h,len(both),np.median([m[True][k] for k in both])-np.median([m[False][k] for k in both]))
run("mo/markout-A-aug.csv",60); run("gate/mo/markout-B-aug.csv",60); run("gate/mo/markout-B-aug.csv",5)
EOF' 2>&1 | tail -4

